DROP VIEW "public"."person_facts";--> statement-breakpoint
ALTER TABLE "companies" ADD COLUMN "decline_reason" varchar(32);--> statement-breakpoint
CREATE VIEW "public"."person_facts" AS (SELECT p.id AS person_id, p.company_id, c.source_key AS company_source_key, c.name AS company_name, c.domain AS company_domain, c.niche AS company_niche, p.source_key, p.full_name, p.first_name, p.last_name, p.title, p.is_compliance, p.is_testimonial, p.testimonial_org, p.origin, p.as_of, p.linkedin_url, CASE WHEN p.is_testimonial THEN NULL::integer WHEN p.title IS NULL THEN CASE WHEN p.origin::text = 'registry'::text THEN 3 ELSE NULL::integer END WHEN c.niche::text = 'sec_ria'::text THEN CASE WHEN p.title ~* '\y(vice president|executive vice|senior vice)\y'::text THEN 3 WHEN p.title ~* '\y(owner|founder|principal|chief executive|ceo|president|managing member|manager)\y'::text THEN 1 WHEN p.title ~* '\y(cio|chief investment|coo|chief operating|managing partner|managing director|partner)\y'::text THEN 2 WHEN p.title ~* '\y(cmo|chief marketing|business development|wealth advisor|financial advisor|portfolio manager|director)\y'::text THEN 3 ELSE NULL::integer END WHEN c.niche::text = 'agencies'::text THEN CASE WHEN p.title ~* '\y(vice president|executive vice|senior vice)\y'::text THEN 3 WHEN p.title ~* '\y(owner|founder|co-founder|chief executive|ceo|president|principal|managing director|managing partner)\y'::text THEN 1 WHEN p.title ~* '\y(coo|chief operating|operations director|head of operations|general manager|managing member|partner)\y'::text THEN 2 WHEN p.title ~* '\y(cmo|chief marketing|creative director|marketing director|account director|business development|head of|director)\y'::text THEN 3 ELSE NULL::integer END WHEN c.niche::text = 'recruiting'::text THEN CASE WHEN p.title ~* '\y(vice president|executive vice|senior vice)\y'::text THEN 3 WHEN p.title ~* '\y(owner|co-owner|founder|co-founder|chief executive|ceo|president|principal|managing member|managing partner)\y'::text THEN 1 WHEN p.title ~* '\y(coo|chief operating|cfo|chief financial|managing director|general manager|partner|member)\y'::text THEN 2 WHEN p.title ~* '\y(director|head of|manager)\y'::text THEN 3 ELSE NULL::integer END ELSE CASE WHEN p.title ~* '\y(vice president|executive vice|senior vice)\y'::text THEN 3 WHEN p.title ~* '\y(owner|founder|co-founder|chief executive|ceo|president|managing member)\y'::text THEN 1 WHEN p.title ~* '\y(coo|chief operating|managing partner|managing director)\y'::text THEN 2 WHEN p.title ~* '\y(director|head of)\y'::text THEN 3 ELSE NULL::integer END END AS role_rank, p.is_compliance OR COALESCE(p.title ~* '\y(compliance|counsel|attorney|paralegal|regulatory)\y'::text, false) AS avoid_emailing_first FROM people p JOIN companies c ON c.id = p.company_id);